INSERT INTO user_addresses (
    user_id, label, recipient_name, phone, country_code, province, city,
    district, detail_address, postal_code, is_default
)
VALUES (
    #{userId}, #{label}, #{recipientName}, #{phone}, #{countryCode}, #{province},
