)

mapper.update:
UPDATE user_addresses
SET is_default = 0
WHERE user_id = #{userId}
  AND deleted_at IS NULL
  AND is_default = 1
AND id != #{exceptId}

UPDATE user_addresses
SET deleted_at = #{deletedAt}
WHERE id = #{id}
  AND user_id = #{userId}
  AND deleted_at IS NULL
